"""Sample synthesis toolkit for the keygen tune. Engine base rate = 8363 Hz."""
import numpy as np, math

SR = 8363          # sample playback rate at note C-4
CYC = 32           # samples per cycle at C-4 -> 261.3 Hz

def norm(x, peak=28000, dc=True):
    x = np.asarray(x, dtype=np.float64)
    if dc:
        x = x - x.mean()
    m = np.abs(x).max()
    if m > 0:
        x = x * (peak / m)
    return x

def to16(x):
    return np.clip(np.round(x), -32768, 32767).astype(np.int16)

def harm_cycle(kind='saw', n=CYC, n_harm=12, duty=0.5, phase=0.0):
    """One cycle of a band-limited waveform, n samples."""
    t = (np.arange(n) + phase) / n
    y = np.zeros(n)
    if kind == 'sine':
        y = np.sin(2*np.pi*t)
    elif kind == 'saw':
        for k in range(1, n_harm+1):
            y += np.sin(2*np.pi*k*t) / k
    elif kind in ('pulse','square'):
        for k in range(1, n_harm+1):
            y += np.sin(2*np.pi*k*duty*k*0 + 2*np.pi*k*t) * np.sin(np.pi*k*duty) / k
    elif kind == 'organ':
        for k,amp in ((1,1.0),(2,0.5),(3,0.33),(4,0.2),(6,0.12),(8,0.08)):
            y += amp*np.sin(2*np.pi*k*t)
    elif kind == 'tri':
        for i,k in enumerate(range(1, n_harm*2, 2)):
            y += ((-1)**i) * np.sin(2*np.pi*k*t) / (k*k)
    return y

def taper_loop(cycles, taper=32, zero=12):
    """Build a looped waveform from an array of cycles with a smooth amplitude
    notch at the wrap point (engine mutes 8 samples at each loop wrap)."""
    y = np.asarray(cycles, dtype=np.float64).copy()
    L = len(y)
    # raised-cosine dip centred on the wrap (index 0), width 2*taper
    w = np.ones(L)
    half = taper
    idx = np.arange(-half, half)          # relative to wrap
    win = 0.5*(1 - np.cos(np.pi*(idx + half)/(2*half)))   # 0 at -half, 1 at +half... 
    # symmetric dip: value 0 at the wrap, 1 at +-half
    dip = 0.5*(1 - np.cos(np.pi*np.abs(idx)/half))
    dip = np.clip(dip, 0, 1)
    for j, i in enumerate(idx):
        w[i % L] = min(w[i % L], dip[j])
    y = y * w
    y[:zero] = 0.0
    y[-zero:] = 0.0
    return y

def attack(x, n=128, shape='exp'):
    x = np.asarray(x, dtype=np.float64).copy()
    if shape == 'exp':
        env = 1 - np.exp(-np.arange(n)/ (n/4.0))
    else:
        env = np.linspace(0, 1, n)
    x[:n] *= env
    return x

def decay_env(n, tau, power=1.0):
    t = np.arange(n)/SR
    return np.exp(-t/tau)**power

def noise(n, seed=0):
    rng = np.random.default_rng(seed)
    return rng.standard_normal(n)

def onepole_lp(x, cut):
    a = math.exp(-2*math.pi*cut/SR)
    y = np.zeros_like(x); prev = 0.0
    for i, v in enumerate(x):
        prev = (1-a)*v + a*prev
        y[i] = prev
    return y

def biquad(x, f0, Q, kind='lp'):
    w0 = 2*math.pi*f0/SR
    alpha = math.sin(w0)/(2*Q)
    c = math.cos(w0)
    if kind == 'lp':
        b0, b1, b2 = (1-c)/2, 1-c, (1-c)/2
    elif kind == 'hp':
        b0, b1, b2 = (1+c)/2, -(1+c), (1+c)/2
    else:  # bp
        b0, b1, b2 = alpha, 0.0, -alpha
    a0, a1, a2 = 1+alpha, -2*c, 1-alpha
    b = np.array([b0,b1,b2])/a0; a = np.array([a1,a2])/a0
    y = np.zeros_like(x); x1=x2=y1=y2=0.0
    for i, v in enumerate(x):
        o = b[0]*v + b[1]*x1 + b[2]*x2 - a[0]*y1 - a[1]*y2
        x2, x1 = x1, v; y2, y1 = y1, o
        y[i] = o
    return y
